export const codeTemplates = {
  python: `def greet(name):\n    if name:\n        print("Hello", name)\n    else:\n        print("Hello world")`,
  javascript: `function greet(name) {\n    if (name) {\n        console.log("Hello", name);\n    } else {\n        console.log("Hello world");\n    }\n}`,
  java: `public class Main {\n    public static void greet(String name) {\n        if (name != null) {\n            System.out.println("Hello " + name);\n        } else {\n            System.out.println("Hello world");\n        }\n    }\n}`,
  c: `void greet(char* name) {\n    if (name != NULL) {\n        printf("Hello %s\\n", name);\n    } else {\n        printf("Hello world\\n");\n    }\n}`,
  cpp: `void greet(string name) {\n    if (!name.empty()) {\n        cout << "Hello " << name << endl;\n    } else {\n        cout << "Hello world" << endl;\n    }\n}`,
  sql: `SELECT \n    CASE \n        WHEN name IS NOT NULL THEN CONCAT('Hello ', name)\n        ELSE 'Hello world'\n    END as greeting\nFROM users;`,
  html: `<div class="greeting">\n    <h1>Hello</h1>\n    <p class="name"></p>\n</div>`
};

export function parseToGraph(src = "") {
  const lines = src.split("\n").map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) {
    const n = { id: "n1", label: "Empty code", shape: "rect" };
    return { nodes: [n], edges: [] };
  }

  const nodes = [];
  const edges = [];
  let idCounter = 0;
  const nextId = () => `n${++idCounter}`;

  const add = (label, shape = "rect") => {
    const id = nextId();
    nodes.push({ id, label, shape });
    return id;
  };

  const start = add("Start");
  let prev = start;

  for (const line of lines) {
    const l = line.toLowerCase();
    if (/^\s*(def|function)\s+/.test(line)) {
      const id = add(line.split("(")[0]);
      edges.push({ from: prev, to: id });
      prev = id;
    } else if (l.startsWith("if ") || l.startsWith("elif ")) {
      const id = add(line, "diamond");
      edges.push({ from: prev, to: id });
      const yes = add("True");
      const no = add("False");
      edges.push({ from: id, to: yes, label: "yes" });
      edges.push({ from: id, to: no, label: "no" });
      prev = yes;
    } else if (l.startsWith("for ") || l.startsWith("while ")) {
      const loop = add(line);
      edges.push({ from: prev, to: loop });
      const end = add("Loop End");
      edges.push({ from: loop, to: end });
      edges.push({ from: end, to: loop });
      prev = end;
    } else {
      const id = add(line);
      edges.push({ from: prev, to: id });
      prev = id;
    }
  }

  return { nodes, edges };
}
